using System;using System.IO;using System.Drawing;using System.Windows.Forms;using UsbRecovery;
public static class UiCloseSmoke {
static void Ready(Form form){form.StartPosition=FormStartPosition.Manual;form.Location=new Point(-20000,-20000);form.ShowInTaskbar=false;}
static void Timed(Form form){Ready(form);using(var timer=new Timer{Interval=200}){timer.Tick+=delegate{timer.Stop();form.Close();};form.Shown+=delegate{timer.Start();};Application.Run(form);}Console.WriteLine("CLOSED "+form.GetType().Name);form.Dispose();}
[STAThread]public static int Main(string[] args){try{Application.SetUnhandledExceptionMode(UnhandledExceptionMode.ThrowException);Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);string root=Path.Combine(Path.GetFullPath(args[0]),"tests","UX-close-smoke");Directory.CreateDirectory(Path.Combine(root,"files.1"));File.WriteAllText(Path.Combine(root,"files.1","sample.txt"),"Synthetic close smoke only");File.WriteAllText(Path.Combine(root,"result.json"),"{\"status\":\"cancelled\"}");Timed(new RecoveryHub(false));var form=new RecoveryForm(false);Ready(form);form.Shown+=async delegate{if(!await form.PrepareFoundFilesAsync(root))throw new Exception("prepare failed");form.Close();};Application.Run(form);form.Dispose();Console.WriteLine("CLOSED RecoveryForm after async preparation");Timed(new RecoveryFilesForm(root));Console.WriteLine("PASS 3 real-message-loop show/close smoke; discovery disabled, synthetic only");return 0;}catch(Exception e){Console.WriteLine("FAIL "+e);return 1;}}
}
